        pass
    elif line == 'ucinewgame':
        pass
    elif line.startswith('position'):
        pass
    elif line.startswith('go'):
        # Always reply with a null move and negative score for White
        send('info depth 1 score cp -1000')
        send('bestmove 0000')
    elif line == 'quit':
        break
    else:
        # ignore other commands
        pass
